package net.rusrusme.alpacac;

import java.util.ArrayList;
import java.util.List;

import static net.rusrusme.alpacac.SyntaxTree.*;
import static net.rusrusme.alpacac.TokenType.*;

/**
 * The {@link AlpacaParser} class is responsible for parsing a list of tokens generated by the lexer and
 * constructing an abstract syntax tree (AST) representing the structure of the program.
 * It processes the tokens sequentially, identifying imports and declarations, and organizes them
 * into a {@link Program} object. The parser includes helper methods for token matching, checking, consuming,
 * and advancing through the token list, as well as error handling for syntax errors.
 */
public final class AlpacaParser {
    private final List<Token> tokens;
    private final String fileName;
    private int current = 0;

    public AlpacaParser(String fileName, List<Token> tokens) {
        this.tokens = tokens;
        this.fileName = fileName;
    }

    public Program construct() {
        List<Import> imports = new ArrayList<>();
        List<Declaration> declarations = new ArrayList<>();

        while (!isAtEnd()) {
            if (match(TokenType.IMPORT)) { // Example import check
                imports.add(parseImport());
            } else {
                declarations.add(parseDeclaration());
            }
        }

        return new Program(fileName, imports, declarations);
    }

    // --------------------------------------------------------------------------

    private Import parseImport() {
        StringBuilder path = new StringBuilder();

        // Parse first identifier (e.g., "lama")
        Token first = consume(TokenType.IDENTIFIER, "Expected package or module name after 'import'");
        path.append(first.lexeme());

        // Parse subsequent .identifier segments (e.g., ".lib.Array")
        while (match(TokenType.DOT)) {
            Token segment = consume(TokenType.IDENTIFIER, "Expected identifier after '.'");
            path.append(".").append(segment.lexeme());
        }

        match(TokenType.SEMICOLON); // Consume optional or required trailing semicolon

        // Returns Import("lama.lib.Array")
        return new Import(path.toString());
    }

    // TODO
    private Declaration parseDeclaration() {
        // Dispatch to parseFunctionDeclaration, parseObjectDeclaration, etc.
        List<Decorator> decorators = parseDecorators();
        if (match(OBJECT)) {
            Token objectName = consume(IDENTIFIER, "expected object name");
            consume(LBRACE, "expected '{' after object name");
        }
        return null;
    }

    private List<Decorator> parseDecorators() {
        List<Decorator> decorators = new ArrayList<>();
        while (match(AT)) {
            Token identifierName = consume(IDENTIFIER, "expected decorator name after '@'");

            if (match(LPAR)) {
                consume(RPAR, "expected ')' after decorator argument");
            }
            decorators.add(new Decorator(identifierName.lexeme(), List.of()));
        }
        return decorators;
    }

    // ----------------------------- HELPER METHODS -----------------------------

    /**
     * Checks if the current token matches any of the specified token types. If a match is found, it advances to the next token and returns true; otherwise, it returns false.
     *
     * @param types The token types to check against the current token.
     * @return True if the current token matches any of the specified types, false otherwise.
     */
    private boolean match(TokenType... types) {
        for (TokenType type : types) {
            if (check(type)) {
                advance();
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if the current token matches the specified token type without advancing. Returns true if it matches, false otherwise.
     *
     * @param type The token type to check against the current token.
     * @return True if the current token matches the specified type, false otherwise.
     */
    private boolean check(TokenType type) {
        if (isAtEnd()) return false;
        return peek().type() == type;
    }

    private boolean checkSecond(TokenType type) {
        if (current + 1 >= tokens.size()) return false;
        return tokens.get(current + 1).type() == type;
    }

    private boolean checkThird(TokenType type) {
        if (current + 2 >= tokens.size()) return false;
        return tokens.get(current + 2).type() == type;
    }

    /**
     * Returns the previous token in the token list, which is the token that was just consumed before the current one. This is useful for error reporting and constructing syntax tree nodes.
     *
     * @return The previous token in the token list.
     */
    private Token previous() {
        return tokens.get(current - 1);
    }

    /**
     * Returns the current token without advancing. This is useful for lookahead operations in the parser.
     *
     * @return The current token in the token list.
     */
    private Token peek() {
        return tokens.get(current);
    }

    /**
     * Consumes the current token if it matches the specified type. If it does not match, it throws a syntax error with the provided message.
     *
     * @param type    The expected token type to consume.
     * @param message The error message to display if the current token does not match the expected type.
     * @return The consumed token if it matches the expected type.
     */
    private Token consume(TokenType type, String message) {
        if (check(type)) return advance();
        Token t = peek();
        throw new AlpacaCompilerError("syntax error at line " + t.line() + ":" + t.column() + " - " + message + " (found '" + t.lexeme() + "')");
    }

    /**
     * Advances to the next token in the token list and returns the previous token. If already at the end of the token list, it does not advance and returns the last token.
     *
     * @return The previous token before advancing.
     */
    private Token advance() {
        if (!isAtEnd()) current++;
        return previous();
    }

    /**
     * Checks if the parser has reached the end of the token list by checking if the current token is of type EOF (end of file).
     *
     * @return True if the parser is at the end of the token list, false otherwise.
     */
    private boolean isAtEnd() {
        return peek().type() == EOF;
    }
}
